    expect(await line.evaluate((node) => parseFloat((node as HTMLElement).style.top))).toBeCloseTo(2 + field.size * (field.ascent / 1024 - 1), 3);
    expect(await right.locator(':scope > [aria-hidden=\"true\"]').evaluate((node) => parseFloat((node as HTMLElement).style.left))).toBeCloseTo(field.width - 2 - creatorGlyphLayout('Right', field).width, 3);
